import{_ as l,H as a,f as t,i as r}from"./chunks/framework.BH2BK_3i.js";const s=JSON.parse('{"title":"29 | 让你数据分析瞬间提效的18个基础功法（下）","description":"","frontmatter":{},"headers":[{"level":3,"title":"12.条件分支计算","slug":"_12-条件分支计算","link":"#_12-条件分支计算","children":[]},{"level":3,"title":"13.统计个数","slug":"_13-统计个数","link":"#_13-统计个数","children":[]},{"level":3,"title":"14.去除重复值","slug":"_14-去除重复值","link":"#_14-去除重复值","children":[]},{"level":3,"title":"15.字符串处理函数","slug":"_15-字符串处理函数","link":"#_15-字符串处理函数","children":[]},{"level":3,"title":"16.数据匹配函数-VLOOKUP","slug":"_16-数据匹配函数-vlookup","link":"#_16-数据匹配函数-vlookup","children":[]},{"level":3,"title":"17.分类汇总和统计","slug":"_17-分类汇总和统计","link":"#_17-分类汇总和统计","children":[]},{"level":3,"title":"18.数据透视表（图）","slug":"_18-数据透视表-图","link":"#_18-数据透视表-图","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后思考","slug":"课后思考","link":"#课后思考","children":[]},{"level":2,"title":"参考资料","slug":"参考资料","link":"#参考资料","children":[]}],"relativePath":"数据分析思维课/29-让你数据分析瞬间提效的18个基础功法（下）.md","filePath":"数据分析思维课/29-让你数据分析瞬间提效的18个基础功法（下）.md","lastUpdated":1779820765000}'),i={name:"数据分析思维课/29-让你数据分析瞬间提效的18个基础功法（下）.md"};function n(o,e,_,h,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_29-让你数据分析瞬间提效的18个基础功法-下" tabindex="-1">29 | 让你数据分析瞬间提效的18个基础功法（下） <a class="header-anchor" href="#_29-让你数据分析瞬间提效的18个基础功法-下" aria-label="Permalink to &quot;29 | 让你数据分析瞬间提效的18个基础功法（下）&quot;">​</a></h1><p>数据给你一双看透本质的眼睛，这里是《数据分析思维课》，我是郭炜。</p><p>上节课我给你讲了做Excel的初级技巧，你在日常使用中绝大部分都会用到。而如果你想要成为Excel高手，还要掌握下面的7种技巧。</p><p>从第12个技巧开始，这些就会是稍微复杂的Excel的公式使用方法了，这些方法可以帮助你在不使用数据库和编程序方法的情况下，使用Excel来处理非常复杂的一些计算逻辑，帮助你解决日常当中遇到的一些复杂问题。</p><p>不要担心，这些并不是Excel里最复杂的“宏编程”，不需要你掌握复杂的编程知识，我用的都是比较简单的例子和方式，让你一看就会一学就懂，通过学习很少量的技巧，助你快速成为一个Excel专家。</p><h3 id="_12-条件分支计算" tabindex="-1">12.条件分支计算 <a class="header-anchor" href="#_12-条件分支计算" aria-label="Permalink to &quot;12.条件分支计算&quot;">​</a></h3><p>我们在日常工作当中经常会遇到某一些数据在某种情况下我们按照这种方法计算，在其他条件下又按另一种方法计算。比如对于计算销售提成来说，大多数公司都是在某一个价格范围里是按照一个销售提成计算，在另一个价格范围里，按照别的销售提成计算。这个时候怎么在Excel里面去处理呢？这就用到了Excel的条件分支计算。使用起来很简单，把逻辑直接写在Excel单元格的公式里就可以。</p><p>有时你在进行Excel计算的时候，还会遇到一些数据出现错误表示#ERROR、或者是出现空值#NA的情况，这时候再进行求和、求平均值等复杂公式计算的时候，你经常会因为这一个数字把一群数字的值都无法计算出来，这样就非常的讨厌。我告诉你，你也可以通过条件分支的情况把这个问题解决掉，具体解决的方法我给你演示下。</p><h3 id="_13-统计个数" tabindex="-1">13.统计个数 <a class="header-anchor" href="#_13-统计个数" aria-label="Permalink to &quot;13.统计个数&quot;">​</a></h3><p>我们经常会统计某一个时间段里的数量是多少，比如我们进行正态分布曲线统计的时候，你就要分片分段来统计不同分段里面的数据分布情况，又或者你去统计某一个班里面不同分数学生的整体情况，也要计算不同分数段不同学生的占比。这个时候我们就会使用统计个数的函数FREQUENCY，使用方法可以参考我给你演示的视频。</p><h3 id="_14-去除重复值" tabindex="-1">14.去除重复值 <a class="header-anchor" href="#_14-去除重复值" aria-label="Permalink to &quot;14.去除重复值&quot;">​</a></h3><p>在使用数据的时候，我们经常会发现给的数据里面有一些重复数据，那么在进行数据统计的时候，我们要做一些去重的处理。有的时候这些去重的处理还不是简单地把重复数据都去掉，而是把一些姓名、身份证号相同，但是可能其它某些列属性不同的数据，按照一定规则分别去重。</p><p>这个时候我们就会有简单和复杂的两种去重方法，下面这个视频就是给你介绍这两种去重方法的，对，在Excel里的去重要比数据库里的Distinct还强大。</p><h3 id="_15-字符串处理函数" tabindex="-1">15.字符串处理函数 <a class="header-anchor" href="#_15-字符串处理函数" aria-label="Permalink to &quot;15.字符串处理函数&quot;">​</a></h3><p>前面给你讲过一个自动填充的技巧，它可以帮助我们找到一些字符之间的关系，然后自动帮你做填充，但是在某些复杂的情况下的时候，Excel无法找到比较好的规律能够自动填充。这个时候你就需要掌握一些基本的字符串的处理函数来帮你去做一些复杂的字符处理。</p><p>例如我们想把手机号码当中的4位变成星号其他位不变，以确保我们的隐私保护，这个时候你就可以使用字符串的函数来方便地解决这个问题。具体方法可以看一下我这个演示，我把最常见的几种字符串使用的函数用比较简单的方法给你讲解了一下。</p><h3 id="_16-数据匹配函数-vlookup" tabindex="-1">16.数据匹配函数-VLOOKUP <a class="header-anchor" href="#_16-数据匹配函数-vlookup" aria-label="Permalink to &quot;16.数据匹配函数-VLOOKUP&quot;">​</a></h3><p>VLOOKUP这个函数是在Excel里面区别普通使用者和高级使用者的一个重要函数，它可以帮助我们在大量数据当中取得我们想要找的相关数据。</p><p>有时候我们也把这个函数用来做数据的比对，例如有两列，我们看看到底这两列中间哪些数据是两边都有的，哪些数据是没有的，我们会使用这个函数来做一下检查。在数据库编程里，我们叫做“关联”。Excel里用这个函数要简单得多，你看了我这个演示，一定可以把它记牢、使用好。</p><h3 id="_17-分类汇总和统计" tabindex="-1">17.分类汇总和统计 <a class="header-anchor" href="#_17-分类汇总和统计" aria-label="Permalink to &quot;17.分类汇总和统计&quot;">​</a></h3><p>我们经常会遇到要在某些分组里做统计，例如从省的维度来统计各城市的销售汇总以及销售的个数，或者是从全国的角度看各省汇总的情况。如果你会SQL，那你就知道我们可以使用数据库里一个叫做GroupBy的方法来取得这些明细数据的分组汇总值。</p><p>其实你不用把数据放到数据库里，在Excel里也可以快速获得这些汇总值，而且公式使用起来也相对简单，具体我来给你演示一下。</p><h3 id="_18-数据透视表-图" tabindex="-1">18.数据透视表（图） <a class="header-anchor" href="#_18-数据透视表-图" aria-label="Permalink to &quot;18.数据透视表（图）&quot;">​</a></h3><p>在Excel里我们经常会面对一个非常明细的数据，想看到它分门别类的汇总或者是基于时间线的一些趋势，从而来做一些数据探索。</p><p>这时候我们就需要既可以分层汇总，还可以去过滤某些条件来针对某些情况下的一些数据进行深入探索，同时我们还希望能够用到Excel的柱状图、折线图、饼图等一些方便的图形辅助我们进行深度的数据探索。</p><p>这种情况下，数据透视表和数据透视图就应运而生了，它可以帮助我们在明细数据里面快速建立一套简单的数据分析视图，能够让你通过简单的拖拉拽快速进行数据探索和图表的生成，从而帮助发现这些数据当中隐含的规律。具体使用方法，你可以参考我这个视频当中的讲解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>到这里，我就把我自己最常用的18种Excel使用技巧教给你了。不知道你发现没有，我们没有像很多Excel课程一样，事无巨细地把所有技巧全都罗列出来，因为我觉得在日常数据分析当中，并不需要记住所有的Excel功能，并且这也是不现实的。</p><p>我介绍的这18种技巧是我和团队在做数据分析的时候，最常用的18种技巧，真的希望你可以通过视频的讲解深深记住。18种其实并不多，我相信你只要花点时间，用心记一记，一定可以掌握。如果你掌握了这18种技巧，在你工作和生活中真正使用的时候，你会发现它可以在你的数据分析、日常管理、自己个人财务分析等诸多方面有非常大的帮助。</p><p>数据给你一双看透本质的眼睛，熟练掌握一种得心用手的数据分析工具，比你只是“会”10种数据分析工具要强大得多。</p><h2 id="课后思考" tabindex="-1">课后思考 <a class="header-anchor" href="#课后思考" aria-label="Permalink to &quot;课后思考&quot;">​</a></h2><p>还有哪些Excel函数你常用的？使用场景是什么呢？分享出来，我们一起提高！</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>你可以点击 <a href="https://pan.baidu.com/s/1DqC7GNgq9DYXOfo-U0BvwA" target="_blank" rel="noreferrer">这里</a>（提取码hnwf）获取我们这节课的Excel文件，方便你进一步学习。</p>',34)])])}const u=l(i,[["render",n]]);export{s as __pageData,u as default};
